UIShieldSparkBoltImage=function(game){var randomBoltIndex=Math.floor(Math.random()*3);Phaser.Image.call(this,game,0,0,'game','shieldSparkBolt'+randomBoltIndex);this.anchor.setTo(0.5,0.84);this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.kill();}
UIShieldSparkBoltImage.prototype=Object.create(Phaser.Image.prototype);UIShieldSparkBoltImage.prototype.constructor=UIShieldSparkBoltImage;UIShieldSparkBoltImage.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}this.alpha=Math.max(0.0,this.alpha-0.035);if(this.alpha==0.0){this.kill();}};UIShieldSparkBoltImage.prototype.spawn=function(x,y,rotation){this.reset(x,y);this.alpha=1.0;this.rotation=rotation+Math.PI*0.5;};UIShieldSparkBoltImage.prototype.retire=function(){this.kill();};